namespace revenge {namespace {
void check(HRESULT hr,const char* label){if(FAILED(hr)){std::ostringstream s;s<<label<<" failed (0x"<<std::hex<<static_cast<unsigned>(hr)<<")";throw std::runtime_error(s.str());}}
struct Handle {HANDLE h=CreateEventW(nullptr,FALSE,FALSE,nullptr);Handle(){if(!h)throw std::runtime_error("CreateEvent failed");}~Handle(){CloseHandle(h);}Handle(const Handle&)=delete;};
const char* vendor(UINT id){switch(id){case 0x10de:return "NVIDIA";case 0x1002:return "AMD";case 0x8086:return "Intel";default:return "Other";}}
struct Gpu {ComPtr<IDXGIAdapter1> adapter;ComPtr<ID3D12Device> device;DXGI_ADAPTER_DESC1 desc{};};
Gpu select(){ComPtr<IDXGIFactory6> factory;check(CreateDXGIFactory2(0,IID_PPV_ARGS(&factory)),"CreateDXGIFactory2");for(UINT i=0;;++i){Gpu g;HRESULT h=factory->EnumAdapterByGpuPreference(i,DXGI_GPU_PREFERENCE_HIGH_PERFORMANCE,IID_PPV_ARGS(&g.adapter));if(h==DXGI_ERROR_NOT_FOUND)break;check(h,"EnumAdapterByGpuPreference");check(g.adapter->GetDesc1(&g.desc),"GetDesc1");if(g.desc.Flags&DXGI_ADAPTER_FLAG_SOFTWARE)continue;if(SUCCEEDED(D3D12CreateDevice(g.adapter.Get(),D3D_FEATURE_LEVEL_12_0,IID_PPV_ARGS(&g.device))))return g;}throw std::runtime_error("No hardware D3D12 FL12_0 adapter");}
void print(const Gpu& g){std::wcout<<L"Adapter: "<<g.desc.Description<<L"\n";std::cout<<"Vendor: "<<vendor(g.desc.VendorId)<<"; dedicated VRAM MiB: "<<(g.desc.DedicatedVideoMemory/1048576)<<"\n";D3D12_FEATURE_DATA_ARCHITECTURE1 a{};if(SUCCEEDED(g.device->CheckFeatureSupport(D3D12_FEATURE_ARCHITECTURE1,&a,sizeof(a))))std::cout<<"UMA: "<<a.UMA<<"; cache-coherent UMA: "<<a.CacheCoherentUMA<<"\n";D3D12_FEATURE_DATA_D3D12_OPTIONS o{};if(SUCCEEDED(g.device->CheckFeatureSupport(D3D12_FEATURE_D3D12_OPTIONS,&o,sizeof(o))))std::cout<<"Resource binding tier: "<<o.ResourceBindingTier<<"\n";D3D12_FEATURE_DATA_D3D12_OPTIONS5 ray{};if(SUCCEEDED(g.device->CheckFeatureSupport(D3D12_FEATURE_D3D12_OPTIONS5,&ray,sizeof(ray))))std::cout<<"DXR tier: "<<ray.RaytracingTier<<"\n";D3D12_FEATURE_DATA_SHADER_MODEL sm{D3D_SHADER_MODEL_6_6};if(SUCCEEDED(g.device->CheckFeatureSupport(D3D12_FEATURE_SHADER_MODEL,&sm,sizeof(sm))))std::cout<<"Shader model (queried up to 6.6): 0x"<<std::hex<<sm.HighestShaderModel<<std::dec<<"\n";ComPtr<IDXGIAdapter3> ad;if(SUCCEEDED(g.adapter.As(&ad))){DXGI_QUERY_VIDEO_MEMORY_INFO m{};if(SUCCEEDED(ad->QueryVideoMemoryInfo(0,DXGI_MEMORY_SEGMENT_GROUP_LOCAL,&m)))std::cout<<"Local memory budget MiB: "<<m.Budget/1048576<<"\n";}}
ComPtr<ID3D12Resource> buffer(ID3D12Device* d,uint64_t size,D3D12_HEAP_TYPE type,D3D12_RESOURCE_STATES state){D3D12_HEAP_PROPERTIES h{};h.Type=type;h.CreationNodeMask=h.VisibleNodeMask=1;D3D12_RESOURCE_DESC r{};r.Dimension=D3D12_RESOURCE_DIMENSION_BUFFER;r.Width=size;r.Height=1;r.DepthOrArraySize=1;r.MipLevels=1;r.SampleDesc.Count=1;r.Layout=D3D12_TEXTURE_LAYOUT_ROW_MAJOR;ComPtr<ID3D12Resource> p;check(d->CreateCommittedResource(&h,D3D12_HEAP_FLAG_NONE,&r,state,nullptr,IID_PPV_ARGS(&p)),"CreateCommittedResource");return p;}
void wait(ID3D12Fence* f,uint64_t value,HANDLE event){auto completed=f->GetCompletedValue();if(completed==UINT64_MAX)throw std::runtime_error("GPU device removed");if(completed>=value)return;check(f->SetEventOnCompletion(value,event),"SetEventOnCompletion");if(WaitForSingleObject(event,30000)!=WAIT_OBJECT_0)throw std::runtime_error("GPU fence wait failed or timed out");completed=f->GetCompletedValue();if(completed==UINT64_MAX||completed<value)throw std::runtime_error("GPU did not complete fence");}
}
int gpu_info(){auto g=select();print(g);return 0;}
int gpu_bench(unsigned frames,unsigned slots,unsigned mib){auto g=select();print(g);auto d=g.device.Get();uint64_t size=uint64_t(mib)*1048576;D3D12_COMMAND_QUEUE_DESC qd{};qd.Type=D3D12_COMMAND_LIST_TYPE_DIRECT;ComPtr<ID3D12CommandQueue> q;check(d->CreateCommandQueue(&qd,IID_PPV_ARGS(&q)),"CreateCommandQueue");ComPtr<ID3D12Fence> f;check(d->CreateFence(0,D3D12_FENCE_FLAG_NONE,IID_PPV_ARGS(&f)),"CreateFence");Handle event;struct Slot{ComPtr<ID3D12CommandAllocator> a;ComPtr<ID3D12GraphicsCommandList> list;ComPtr<ID3D12Resource> dst;uint64_t fence=0;};std::vector<Slot> ring(slots);auto src=buffer(d,size,D3D12_HEAP_TYPE_UPLOAD,D3D12_RESOURCE_STATE_GENERIC_READ);auto read=buffer(d,size,D3D12_HEAP_TYPE_READBACK,D3D12_RESOURCE_STATE_COPY_DEST);void* data=nullptr;D3D12_RANGE empty{0,0};check(src->Map(0,&empty,&data),"Map upload");std::memset(data,0xa5,static_cast<size_t>(size));src->Unmap(0,nullptr);for(auto& s:ring){s.dst=buffer(d,size,D3D12_HEAP_TYPE_DEFAULT,D3D12_RESOURCE_STATE_COPY_DEST);check(d->CreateCommandAllocator(D3D12_COMMAND_LIST_TYPE_DIRECT,IID_PPV_ARGS(&s.a)),"CreateCommandAllocator");check(d->CreateCommandList(0,D3D12_COMMAND_LIST_TYPE_DIRECT,s.a.Get(),nullptr,IID_PPV_ARGS(&s.list)),"CreateCommandList");check(s.list->Close(),"Close initial list");}auto start=std::chrono::steady_clock::now();uint64_t seq=0;for(unsigned i=0;i<frames;++i){auto& s=ring[i%slots];if(s.fence)wait(f.Get(),s.fence,event.h);check(s.a->Reset(),"Reset allocator");check(s.list->Reset(s.a.Get(),nullptr),"Reset list");s.list->CopyBufferRegion(s.dst.Get(),0,src.Get(),0,size);check(s.list->Close(),"Close list");ID3D12CommandList* lists[]={s.list.Get()};q->ExecuteCommandLists(1,lists);s.fence=++seq;check(q->Signal(f.Get(),seq),"Signal");}wait(f.Get(),seq,event.h);double sec=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();auto& last=ring[(frames-1)%slots];check(last.a->Reset(),"Reset readback allocator");check(last.list->Reset(last.a.Get(),nullptr),"Reset readback list");D3D12_RESOURCE_BARRIER b{};b.Type=D3D12_RESOURCE_BARRIER_TYPE_TRANSITION;b.Transition.pResource=last.dst.Get();b.Transition.Subresource=D3D12_RESOURCE_BARRIER_ALL_SUBRESOURCES;b.Transition.StateBefore=D3D12_RESOURCE_STATE_COPY_DEST;b.Transition.StateAfter=D3D12_RESOURCE_STATE_COPY_SOURCE;last.list->ResourceBarrier(1,&b);last.list->CopyBufferRegion(read.Get(),0,last.dst.Get(),0,size);check(last.list->Close(),"Close readback list");ID3D12CommandList* lists[]={last.list.Get()};q->ExecuteCommandLists(1,lists);check(q->Signal(f.Get(),++seq),"Signal readback");wait(f.Get(),seq,event.h);D3D12_RANGE range{0,static_cast<SIZE_T>(size)};check(read->Map(0,&range,&data),"Map readback");auto p=static_cast<const unsigned char*>(data);bool good=true;for(uint64_t i=0;i<size;++i)if(p[i]!=0xa5){good=false;break;}read->Unmap(0,&empty);if(!good)throw std::runtime_error("GPU copy verification failed");std::cout<<"Verified final copy. Synthetic transfer throughput: "<<(frames*double(mib)/sec)<<" MiB/s; mean submission/completion wall time "<<sec*1000/frames<<" ms; slots="<<slots<<". Not game FPS.\n";return 0;}
}
namespace revenge {
int gpu_compute(const std::filesystem::path& shader){
 // This is a known-answer test for samples/test.hlsl, not a general shader runner.
 std::ifstream in(shader,std::ios::binary|std::ios::ate); if(!in)throw std::runtime_error("cannot open sample shader");auto size=in.tellg();if(size<=0||size>std::streamoff(16*1024*1024))throw std::runtime_error("invalid sample shader size");std::vector<char> code(static_cast<size_t>(size));in.seekg(0);if(!in.read(code.data(),size))throw std::runtime_error("shader read failed");
 auto g=select();print(g);auto d=g.device.Get();constexpr UINT count=4096;constexpr UINT bytes=count*4;D3D12_ROOT_PARAMETER param{};param.ParameterType=D3D12_ROOT_PARAMETER_TYPE_UAV;param.Descriptor.ShaderRegister=0;param.ShaderVisibility=D3D12_SHADER_VISIBILITY_ALL;D3D12_ROOT_SIGNATURE_DESC desc{};desc.NumParameters=1;desc.pParameters=&param;ComPtr<ID3DBlob> sig,error;check(D3D12SerializeRootSignature(&desc,D3D_ROOT_SIGNATURE_VERSION_1,&sig,&error),"Serialize root signature");ComPtr<ID3D12RootSignature> root;check(d->CreateRootSignature(0,sig->GetBufferPointer(),sig->GetBufferSize(),IID_PPV_ARGS(&root)),"CreateRootSignature");D3D12_COMPUTE_PIPELINE_STATE_DESC pd{};pd.pRootSignature=root.Get();pd.CS={code.data(),code.size()};ComPtr<ID3D12PipelineState> pso;auto pstart=std::chrono::steady_clock::now();check(d->CreateComputePipelineState(&pd,IID_PPV_ARGS(&pso)),"CreateComputePipelineState");std::cout<<"Compute PSO creation ms: "<<std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-pstart).count()<<"\n";
 D3D12_HEAP_PROPERTIES h{};h.Type=D3D12_HEAP_TYPE_DEFAULT;h.CreationNodeMask=h.VisibleNodeMask=1;D3D12_RESOURCE_DESC r{};r.Dimension=D3D12_RESOURCE_DIMENSION_BUFFER;r.Width=bytes;r.Height=1;r.DepthOrArraySize=1;r.MipLevels=1;r.SampleDesc.Count=1;r.Layout=D3D12_TEXTURE_LAYOUT_ROW_MAJOR;r.Flags=D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS;ComPtr<ID3D12Resource> output;check(d->CreateCommittedResource(&h,D3D12_HEAP_FLAG_NONE,&r,D3D12_RESOURCE_STATE_UNORDERED_ACCESS,nullptr,IID_PPV_ARGS(&output)),"Create UAV");auto read=buffer(d,bytes,D3D12_HEAP_TYPE_READBACK,D3D12_RESOURCE_STATE_COPY_DEST);
 D3D12_COMMAND_QUEUE_DESC qd{};qd.Type=D3D12_COMMAND_LIST_TYPE_DIRECT;ComPtr<ID3D12CommandQueue> q;check(d->CreateCommandQueue(&qd,IID_PPV_ARGS(&q)),"Create queue");ComPtr<ID3D12CommandAllocator> a;check(d->CreateCommandAllocator(qd.Type,IID_PPV_ARGS(&a)),"Create allocator");ComPtr<ID3D12GraphicsCommandList> list;check(d->CreateCommandList(0,qd.Type,a.Get(),pso.Get(),IID_PPV_ARGS(&list)),"Create list");list->SetComputeRootSignature(root.Get());list->SetComputeRootUnorderedAccessView(0,output->GetGPUVirtualAddress());list->Dispatch(count/64,1,1);D3D12_RESOURCE_BARRIER barrier{};barrier.Type=D3D12_RESOURCE_BARRIER_TYPE_TRANSITION;barrier.Transition.pResource=output.Get();barrier.Transition.Subresource=D3D12_RESOURCE_BARRIER_ALL_SUBRESOURCES;barrier.Transition.StateBefore=D3D12_RESOURCE_STATE_UNORDERED_ACCESS;barrier.Transition.StateAfter=D3D12_RESOURCE_STATE_COPY_SOURCE;list->ResourceBarrier(1,&barrier);list->CopyBufferRegion(read.Get(),0,output.Get(),0,bytes);check(list->Close(),"Close list");ComPtr<ID3D12Fence> fence;check(d->CreateFence(0,D3D12_FENCE_FLAG_NONE,IID_PPV_ARGS(&fence)),"Create fence");Handle event;ID3D12CommandList* lists[]={list.Get()};q->ExecuteCommandLists(1,lists);check(q->Signal(fence.Get(),1),"Signal");wait(fence.Get(),1,event.h);D3D12_RANGE range{0,bytes},empty{0,0};void* data=nullptr;check(read->Map(0,&range,&data),"Map result");bool valid=true;auto v=static_cast<const uint32_t*>(data);for(UINT i=0;i<count;++i)if(v[i]!=i*3+1){valid=false;break;}read->Unmap(0,&empty);if(!valid)throw std::runtime_error("Compute known-answer test failed");std::cout<<"Verified all "<<count<<" compute results.\n";return 0;
}
}
